from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter()


@router.get("/learning", response_class=HTMLResponse)
def learning_page():
    return r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>FX · Learning</title>
<style>
:root{color-scheme:dark;--bg:#090a0c;--panel:#111317;--line:#292d33;--text:#f3f4f6;--muted:#959ba5;--bad:#ff858b}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{display:grid;grid-template-columns:220px 1fr;min-height:100vh}.side{padding:20px 14px;border-right:1px solid var(--line);position:sticky;top:0;height:100vh}.brand{font-size:19px;font-weight:780;margin:0 8px 25px}.brand span{color:var(--muted);font-weight:500}a{display:block;color:#b7bbc2;text-decoration:none;padding:9px;border-radius:7px;margin:2px 0}a:hover,a.active{background:#181a1f;color:#fff}main{padding:34px;max-width:1400px;width:100%}h1{font-size:31px;letter-spacing:-1px;margin:0 0 7px}.lead{color:var(--muted);max-width:800px;line-height:1.55}.control{display:grid;grid-template-columns:1fr auto;align-items:center;gap:18px;background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:18px;margin:24px 0}.control h2{font-size:16px;margin:0 0 7px}.control-state{color:var(--muted);font-size:12px;line-height:1.55}.actions{display:flex;gap:8px}button{border:0;border-radius:8px;padding:10px 14px;font-weight:750;cursor:pointer}.primary{background:#f2f3f5;color:#101114}.secondary{background:#202329;color:#d7dade;border:1px solid #34383f}.metrics{display:grid;grid-template-columns:repeat(5,minmax(130px,1fr));gap:10px;margin:26px 0}.guide{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:18px;margin:18px 0}.guide h2{font-size:17px;margin:0 0 12px}.steps{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.step{border-left:2px solid var(--line);padding:4px 10px;color:var(--muted);font-size:12px;line-height:1.45}.step b{display:block;color:var(--text);margin-bottom:4px}.metric,.card{background:var(--panel);border:1px solid var(--line);border-radius:12px}.metric{padding:15px}.metric small{color:var(--muted);display:block}.metric b{font-size:23px;display:block;margin-top:9px}.bar{display:flex;gap:10px;align-items:center;justify-content:space-between;margin:25px 0 12px}.bar h2{font-size:17px;margin:0}.pill{border:1px solid var(--line);border-radius:99px;padding:6px 9px;color:var(--muted);font-size:11px}.card{padding:16px}.top{display:flex;justify-content:space-between;gap:10px}.name{font-weight:750;text-transform:capitalize}.state{font-size:10px;color:var(--muted);letter-spacing:.06em}.state.research{color:#70dca0}.state.failed{color:var(--bad)}.context,.why{color:var(--muted);margin-top:8px;font-size:12px;line-height:1.45}.scores{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:14px}.score{border-top:1px solid var(--line);padding-top:9px}.score small{color:var(--muted);display:block;font-size:10px}.score b{font-size:13px;margin-top:4px;display:block}.grid{display:block}.asset-group{border-top:1px solid var(--line);padding-top:18px;margin:0 0 28px}.asset-title{font-size:19px;margin:0 0 5px}.asset-note{color:var(--muted);font-size:11px;margin-bottom:12px}.evidence-group{margin:0 0 8px;border:1px solid var(--line);border-radius:10px;background:var(--panel);overflow:hidden}.group-head{display:grid;grid-template-columns:minmax(130px,1fr) auto auto auto;gap:18px;align-items:center;padding:12px 14px;cursor:pointer;list-style:none}.group-head::-webkit-details-marker{display:none}.group-head:hover{background:#171a1f}.group-name{font-weight:760}.group-stat{color:var(--muted);font-size:11px;white-space:nowrap}.group-toggle{color:var(--muted);font-size:16px}.evidence-group[open] .group-toggle{transform:rotate(90deg)}.group-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:8px;padding:0 10px 10px;border-top:1px solid var(--line);padding-top:10px}:focus-visible{outline:2px solid #fff;outline-offset:2px}
@media(max-width:850px){.shell{display:block}.side{height:auto;position:static;border-right:0;border-bottom:1px solid var(--line)}main{padding:22px}.metrics{grid-template-columns:repeat(2,1fr)}.steps{grid-template-columns:1fr}.control{grid-template-columns:1fr}.group-head{grid-template-columns:1fr auto}.group-head .group-stat:nth-child(3){display:none}}
</style></head><body><div class="shell"><aside class="side"><div class="brand">FX <span>Terminal</span></div><a href="/terminal">Chat & Markets</a><a href="/learning" class="active">Bot Learning</a><a href="/journal">Trade Journal</a><a href="/training">One-off Training</a></aside>
<main><h1>How the bots are learning</h1><p class="lead">FX trains challenger models across approved markets while the computer is running. Every result is tested on later unseen data. Learning never sends a trade or promotes itself.</p>
<section class="control"><div><h2>Continuous learning</h2><div id="continuous" class="control-state">Checking the local worker…</div></div><div class="actions"><button class="primary" onclick="setLearning(true)">Start learning</button><button class="secondary" onclick="setLearning(false)">Pause safely</button></div></section>
<section class="guide"><h2>How a working brain becomes qualified</h2><div class="steps"><div class="step"><b>1 · Train</b>Chronological market history only.</div><div class="step"><b>2 · Unseen test</b>AUC and balanced accuracy must each reach 0.52.</div><div class="step"><b>3 · Walk-forward</b>Repeated later windows must also pass 0.52.</div><div class="step"><b>4 · Calibrate and stress</b>Probability, costs, stability and drawdown need evidence.</div><div class="step"><b>5 · Paper examination</b>Only an immutable version that clears every gate can assist a protected order.</div></div><p class="lead">WORKING · NOT QUALIFIED means the code completed normally but did not prove a reliable edge. FX never changes that label merely because a model ran more times.</p></section><section id="metrics" class="metrics"></section><div class="bar"><h2>Training evidence</h2><span class="pill">85% calibrated probability required per trade</span></div><section id="grid" class="grid"><p class="lead">Loading local evidence…</p></section></main></div>
<script>
const pct=v=>v==null?'Unavailable':(Number(v)*100).toFixed(1)+'%';
function node(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function metric(label,value){const d=node('div','metric');d.append(node('small','',label),node('b','',String(value)));return d}
function score(label,value){const d=node('div','score');d.append(node('small','',label),node('b','',value));return d}
function describe(s){if(s.status==='PAUSED_RESOURCE_PRESSURE')return 'Paused to protect this Mac · CPU '+Number(s.cpu_percent||0).toFixed(1)+'% exceeds safe limit '+Number(s.max_cpu_percent||85).toFixed(0)+'% · the worker is alive and retries every '+Number(s.resource_retry_seconds||30)+' seconds';const state=String(s.status||'STOPPED').replaceAll('_',' '),current=s.current;return state+(current?' · '+current.name+' · '+current.timeframe:'')+' · '+Number(s.completed_jobs||0)+' completed · '+Number(s.failed_jobs||0)+' failed safely · '+Number(s.universe_size||0)+' approved targets'}
async function setLearning(run){const el=document.getElementById('continuous');el.textContent=run?'Starting the local research queue…':'Finishing the current safe checkpoint…';try{const data=await fetch(run?'/api/learning/start':'/api/learning/stop',{method:'POST'}).then(r=>r.json());el.textContent=describe(data.continuous||{})}catch{el.textContent='FX could not change the learning worker state.'}}
function evidenceCard(r){const c=node('article','card'),top=node('div','top'),state=node('div','state',r.stage==='RESEARCH_COMPLETE'?'WORKING · NOT QUALIFIED':r.stage.replaceAll('_',' '));if(r.stage==='RESEARCH_COMPLETE')state.classList.add('research');if(r.stage==='RUN_FAILED')state.classList.add('failed');top.append(node('div','name',(r.model||'model').replaceAll('_',' ')),state);c.append(top,node('div','context',(r.timeframe||'Unknown timeframe')+' · '+(r.training_observations||0)+' training observations'),node('div','why',r.explanation));const scores=node('div','scores');scores.append(score('Unseen accuracy',pct(r.unseen_accuracy)),score('Unseen AUC',r.unseen_auc==null?'Unavailable':Number(r.unseen_auc).toFixed(3)),score('Walk-forward AUC',r.walk_forward_auc==null?'Unavailable':Number(r.walk_forward_auc).toFixed(3)));c.append(scores);return c}
async function load(){
const openGroups=new Set([...document.querySelectorAll('.evidence-group[open]')].map(item=>item.dataset.key));
const [data,universeData]=await Promise.all([fetch('/api/learning/overview').then(r=>r.json()),fetch('/api/learning/universe').then(r=>r.json())]),s=data.summary,m=document.getElementById('metrics');
document.getElementById('continuous').textContent=describe(data.continuous||{});
m.replaceChildren(metric('Training runs',s.total_runs),metric('Working brains',s.completed_safely||0),metric('Qualification blocked',s.qualification_blocked||0),metric('Paper eligible',s.paper_eligible),metric('Trade threshold',pct(s.required_trade_probability)));
const root=document.getElementById('grid');root.replaceChildren();
const assets=[...new Set((universeData.instruments||[]).map(item=>item.asset_class))];
const byAsset=new Map(assets.map(asset=>[asset,[]]));
data.records.forEach(record=>{const asset=record.asset_class||'Other research';if(!byAsset.has(asset))byAsset.set(asset,[]);byAsset.get(asset).push(record)});
byAsset.forEach((assetRecords,asset)=>{
const section=node('section','asset-group'),targetCount=(universeData.instruments||[]).filter(item=>item.asset_class===asset).length;
section.append(node('h3','asset-title',asset),node('div','asset-note',targetCount+' core learning targets · '+assetRecords.length+' recorded model runs'));
if(!assetRecords.length){section.append(node('p','lead','Waiting for the first completed validation run in this group.'));root.append(section);return}
const instruments=new Map();
assetRecords.forEach(record=>{const key=record.instrument||'Unknown instrument';if(!instruments.has(key))instruments.set(key,[]);instruments.get(key).push(record)});
instruments.forEach((records,instrument)=>{
const group=node('details','evidence-group');group.dataset.key=asset+'|'+instrument;group.open=openGroups.has(group.dataset.key);
const head=node('summary','group-head');
const blocked=records.filter(record=>String(record.stage).toUpperCase()==='RESEARCH_COMPLETE').length;
const failed=records.filter(record=>String(record.stage).toUpperCase()==='RUN_FAILED').length;
const eligible=records.filter(record=>String(record.stage).toUpperCase()==='PAPER_ELIGIBLE').length;
const validAccuracies=records.map(record=>record.unseen_accuracy).filter(value=>value!=null).map(Number);
const best=validAccuracies.length?Math.max(...validAccuracies):null;
head.append(node('span','group-name',instrument),node('span','group-stat',records.length+' model runs'),node('span','group-stat',(eligible?eligible+' eligible · ':'')+blocked+' working / blocked'+(failed?' · '+failed+' failed':'')+' · best '+pct(best)),node('span','group-toggle','›'));
const cards=node('div','group-grid');records.forEach(record=>cards.append(evidenceCard(record)));
group.append(head,cards);section.append(group)
});root.append(section)
})}
load().catch(()=>{document.getElementById('grid').textContent='FX could not load local training evidence.'});setInterval(load,10000);
</script></body></html>"""
